-- Analysis of the backgrounds added after 0010 (Background 365..437), one JSON document each, into public.catalogue_analysis.
--
-- Source: "Saree BG/backgrounds/N.json", matched to 'Background N' (the same rule as 0010). Only backgrounds that have no
-- analysis yet are filled: a background that already has one is left exactly as it is (on conflict do nothing).
--
-- Stops and rolls everything back if a record has no catalogue row.

create temp table _staged (
  num       integer not null,
  drive_id  text not null,
  doc       jsonb not null
) on commit drop;


do $$
declare missing text;
begin
  select string_agg(s.drive_id, ', ') into missing
  from _staged s
  left join public.backgrounds b on b.name = 'Background ' || s.num
  where b.id is null;
  if missing is not null then
    raise exception 'No catalogue row for these analysis records: %', missing;
  end if;
end
$$;

select b.id, s.drive_id, s.doc
from _staged s
join public.backgrounds b on b.name = 'Background ' || s.num
on conflict (background_id) where background_id is not null do nothing;
